local LensGrinder = {}
local PRODUCTS = {
    spectacle = { name = "Očala", glassCost = 2, metalCost = 1, time = 5, cost = 80, visionBonus = 10, happiness = 3, description = "Za slabe oči." },
    magnifier = { name = "Povečevalo", glassCost = 3, metalCost = 1, time = 4, cost = 60, visionBonus = 15, knowledge = 5, description = "Za branje in raziskovanje." },
    telescope = { name = "Daljnogled", glassCost = 5, metalCost = 3, woodCost = 2, time = 14, cost = 300, visionBonus = 40, knowledge = 20, prestige = 8, description = "Za opazovanje zvezd." },
    microscope = { name = "Mikroskop", glassCost = 4, metalCost = 3, time = 20, cost = 500, visionBonus = 30, knowledge = 30, prestige = 12, description = "Za majhne stvari." },
    lens = { name = "Leča", glassCost = 2, time = 3, cost = 30, visionBonus = 5, description = "Posamezna optična leča." },
    reading_stone = { name = "Branje kamen", glassCost = 3, time = 2, cost = 40, visionBonus = 8, happiness = 1, description = "Polkrogla leča za branje." },
}
local BUILDINGS = {
    workshop = { name = "Lečarska delavnica", cost = { gold = 400, wood = 100, iron = 30 }, upkeep = 10, qualityBonus = 5 },
    grinding_room = { name = "Brusilnica", cost = { gold = 1200, wood = 200, stone = 300, iron = 50 }, upkeep = 30, qualityBonus = 20 },
    optical_lab = { name = "Optični laboratorij", cost = { gold = 2500, wood = 300, stone = 500, iron = 100 }, upkeep = 50, qualityBonus = 30, prestigeBonus = 10 },
    royal_optician = { name = "Kraljevski optik", cost = { gold = 5000, wood = 400, stone = 800, iron = 200 }, upkeep = 100, qualityBonus = 45, prestigeBonus = 20 },
}
LensGrinder.glassStock = 12; LensGrinder.metalStock = 8; LensGrinder.woodStock = 10
LensGrinder.productStock = {}; LensGrinder.buildings = {}; LensGrinder.grinder = nil; LensGrinder.activeMaking = {}; LensGrinder.totalProducts = 0; LensGrinder.dayTimer = 0
function LensGrinder.init() LensGrinder.glassStock=12; LensGrinder.metalStock=8; LensGrinder.woodStock=10; LensGrinder.productStock={}; LensGrinder.buildings={}; LensGrinder.grinder=nil; LensGrinder.activeMaking={}; LensGrinder.totalProducts=0; LensGrinder.dayTimer=0; print("[LensGrinder] Royal Lens Grinder & Optician System initialized (6 products, 4 buildings)") end
function LensGrinder.hireGrinder(n,s) s=s or math.random(40,85); local c=400+s*8; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LensGrinder.grinder={name=n or ("Lečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lečar najet: %s (spretnost: %d)",LensGrinder.grinder.name,s),"success") end; return true end
function LensGrinder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LensGrinder.build(id) local ok,e=LensGrinder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LensGrinder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LensGrinder.getQualityBonus() local b=0; for _,bd in ipairs(LensGrinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LensGrinder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and LensGrinder.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.metalCost and LensGrinder.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.woodCost and LensGrinder.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if #LensGrinder.buildings==0 then return false,"Potrebna delavnica" end; if not LensGrinder.grinder then return false,"Potreben lečar" end; return true end
function LensGrinder.make(pt) local ok,e=LensGrinder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then LensGrinder.glassStock=LensGrinder.glassStock-d.glassCost end; if d.metalCost then LensGrinder.metalStock=LensGrinder.metalStock-d.metalCost end; if d.woodCost then LensGrinder.woodStock=LensGrinder.woodStock-d.woodCost end; local t=d.time; if LensGrinder.grinder then t=math.max(1,t-math.floor(LensGrinder.grinder.skill/12)) end; table.insert(LensGrinder.activeMaking,{id="lens_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,visionBonus=d.visionBonus or 0,happiness=d.happiness or 0,knowledge=d.knowledge or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brušenje: %s (%d dni)",d.name,t),"info") end; return true end
function LensGrinder.completeMaking(m) local q=1.0+(LensGrinder.getQualityBonus()/100); if LensGrinder.grinder then q=q+(LensGrinder.grinder.skill/200) end; q=math.min(2.0,q); LensGrinder.productStock[m.productType]=(LensGrinder.productStock[m.productType] or 0)+1; LensGrinder.totalProducts=LensGrinder.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if LensGrinder.grinder then LensGrinder.grinder.itemsMade=LensGrinder.grinder.itemsMade+1; if math.random()<0.15 then LensGrinder.grinder.skill=math.min(100,LensGrinder.grinder.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Leča izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function LensGrinder.update(dt) if not _G.state then return end; LensGrinder.dayTimer=LensGrinder.dayTimer+dt; if LensGrinder.dayTimer>=30 then LensGrinder.dayTimer=0; for i=#LensGrinder.activeMaking,1,-1 do local m=LensGrinder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LensGrinder.completeMaking(m); table.remove(LensGrinder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LensGrinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LensGrinder.grinder then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LensGrinder.getStats() return {glassStock=LensGrinder.glassStock,metalStock=LensGrinder.metalStock,productStock=LensGrinder.productStock,numBuildings=#LensGrinder.buildings,hasGrinder=LensGrinder.grinder~=nil,grinderName=LensGrinder.grinder and LensGrinder.grinder.name or "—",grinderSkill=LensGrinder.grinder and LensGrinder.grinder.skill or 0,activeMaking=#LensGrinder.activeMaking,totalProducts=LensGrinder.totalProducts} end
return LensGrinder
